-- Atualiza os tutoriais existentes e completa os assuntos da Central de Ajuda.
do $migration$
declare
  category jsonb;
  article jsonb;
  category_id_value uuid;
  article_id_value uuid;
  article_order integer := 0;
begin
  for category in select value from jsonb_array_elements($categories$[
    {"code":"transactions","label":"Transações","icon":"arrow-left-right","color":"#10B981"},
    {"code":"cards","label":"Cartões","icon":"credit-card","color":"#2563EB"},
    {"code":"goals","label":"Metas","icon":"target","color":"#F59E0B"},
    {"code":"groups","label":"Grupos","icon":"message-circle","color":"#8B5CF6"},
    {"code":"budgets","label":"Orçamentos","icon":"chart-pie","color":"#EF4444"},
    {"code":"accounts","label":"Contas","icon":"landmark","color":"#4F46E5"},
    {"code":"voice","label":"Voz e leitura de comprovantes","icon":"mic","color":"#EC4899"},
    {"code":"reports","label":"Relatórios","icon":"newspaper","color":"#06B6D4"},
    {"code":"recurring","label":"Transações recorrentes","icon":"repeat","color":"#2563EB"},
    {"code":"imports","label":"Importação de dados","icon":"file-spreadsheet","color":"#10B981"},
    {"code":"income-tax","label":"Imposto de Renda","icon":"receipt","color":"#06B6D4"},
    {"code":"plans","label":"Planos e assinatura","icon":"crown","color":"#F59E0B"},
