    {"code":"support","label":"Ajuda e suporte","icon":"message-circle","color":"#10B981"}
  ]$categories$::jsonb) loop
    insert into public.help_categories (code, label, icon, color, display_order)
    values (category->>'code', category->>'label', category->>'icon', category->>'color',
      case category->>'code'
        when 'transactions' then 1 when 'cards' then 2 when 'goals' then 3
        when 'groups' then 4 when 'budgets' then 5 when 'accounts' then 6
        when 'voice' then 7 when 'reports' then 8 when 'recurring' then 9
        when 'imports' then 10 when 'income-tax' then 11 when 'plans' then 12
        when 'profile' then 13 when 'security' then 14 when 'notifications' then 15 else 16 end)
    on conflict (code) do update set label = excluded.label, icon = excluded.icon,
      color = excluded.color, display_order = excluded.display_order, is_active = true;
  end loop;

  for article in select value from jsonb_array_elements($articles$[
    {"category":"security","title":"Como criar uma conta no nitin?","tip":"Use um e-mail ao qual você tenha acesso para confirmar o cadastro e recuperar a senha.","steps":["Na tela inicial de acesso, inicie o cadastro de uma nova conta.","Preencha os dados solicitados e confira seu CPF, e-mail e demais informações antes de avançar.","Leia os termos de uso e a política de privacidade apresentados e defina sua senha.","Conclua o cadastro e siga as instruções de confirmação de e-mail exibidas antes de entrar no app."]},
    {"category":"security","title":"Como sair da minha conta?","tip":"Em um dispositivo compartilhado, saia da conta ao terminar de usar o app.","steps":["Salve os lançamentos e alterações que estiver fazendo.","Abra a aba Mais e localize a opção de sair da conta.","Toque em Sair e aguarde o retorno à tela de acesso.","Para voltar a usar sua conta, entre novamente com seu CPF e senha e conclua as verificações solicitadas."]},
    {"category":"reports","title":"Como acompanhar o resumo da Home?","tip":"Use Relatórios para consultar outros períodos e análises disponíveis no seu plano.","steps":["Abra a Home para consultar o saldo, as Entradas e as Saídas do mês atual.","Use o ícone de olho no cabeçalho para ocultar ou mostrar os valores.","Consulte o fluxo semanal, as categorias do mês e as últimas movimentações.","Use os atalhos de Metas, Grupos e Contas para abrir os detalhes de cada área."]},
    {"category":"security","title":"Como entrar na conta ou recuperar a senha?","tip":"Nunca compartilhe sua senha nem os códigos do autenticador.","steps":["Na tela de acesso, informe seu CPF e avance para a etapa de senha.","Digite sua senha e toque em Entrar. Conclua a verificação do autenticador se ela estiver ativada.","Se não lembrar a senha, use Esqueci a senha e siga as instruções de recuperação apresentadas.","Abra o link recebido no e-mail de cadastro e escolha uma nova senha. Depois de salvá-la, retorne ao app."]},
    {"category":"plans","title":"Como restaurar uma assinatura?","tip":"Use a mesma conta da loja utilizada na contratação.","steps":["Abra Mais, Planos.","Localize a opção de restaurar compras e inicie a restauração.","Aguarde a consulta da assinatura e a atualização do plano.","Se nenhuma assinatura ativa for encontrada, confira a conta Google Play usada na compra e entre em contato com o suporte se precisar."]},
    {"category":"transactions","title":"Como registrar uma nova transação?","popular":true,"tip":"Confira valor, data e conta antes de salvar.","steps":["Na Home ou em Transações, abra o lançamento e escolha Manual.","Selecione Despesa ou Receita e preencha descrição, valor e data.","Escolha a conta, uma categoria e o método de pagamento.","Revise os dados e toque em Salvar. Confira o lançamento no extrato."]},
    {"category":"transactions","title":"Como buscar, filtrar, editar ou excluir uma transação?","tip":"Transferências, pagamentos de fatura e lançamentos de grupo têm ações próprias.","steps":["Abra Transações e selecione o período desejado.","Use a busca e os filtros de conta, método de pagamento e tipo para localizar o lançamento.","Toque na transação para abrir os detalhes. Nos lançamentos editáveis, use Editar e depois Salvar.","Para remover um lançamento, use a ação de exclusão disponível e leia a confirmação antes de continuar."]},
    {"category":"cards","title":"Como cadastrar ou editar um cartão?","tip":"Confira os dias de fechamento e vencimento para organizar as faturas.","steps":["Abra a aba Cartões e toque em Criar.","Preencha os dados do cartão, o limite e os dias de fechamento e vencimento.","Revise e salve o cadastro.","Para alterar os dados depois, use o ícone de edição do cartão."]},
    {"category":"cards","title":"Como lançar uma compra no cartão?","popular":true,"tip":"Confira a quantidade de parcelas e os valores antes de confirmar.","steps":["Abra Cartões e toque em Lançar compra.","Selecione o cartão e preencha descrição, valor e data da compra.","Escolha a categoria e a quantidade de parcelas.","Salve e confira os lançamentos nas faturas correspondentes."]},
    {"category":"cards","title":"Como consultar e pagar uma fatura?","tip":"A fatura em aberto informa quando o pagamento estará disponível.","steps":["Abra Cartões e consulte o painel de fatura do cartão desejado.","Abra os detalhes para conferir as compras, o total e o vencimento.","Quando a fatura permitir pagamento, abra a ação de pagar e escolha a conta de origem e o valor.","Revise e confirme o registro. Consulte o extrato para conferir o pagamento e, se necessário, a ação Desfazer pagamento."]},
    {"category":"goals","title":"Como criar e acompanhar uma meta?","tip":"O valor inicial, os aportes e as retiradas compõem o progresso da meta.","steps":["Em Mais, abra Metas e inicie uma nova meta.","Informe o nome, o valor desejado, o valor inicial e o prazo.","Escolha um ícone e uma cor e salve.","Acompanhe o progresso e use a edição da meta para ajustar seus dados."]},
    {"category":"goals","title":"Como adicionar ou retirar dinheiro de uma meta?","tip":"Use uma conta com saldo suficiente para o aporte e confira o saldo disponível antes de retirar.","steps":["Abra Mais, Metas e localize a meta.","Toque em Adicionar para fazer um aporte ou em Retirar para devolver parte da reserva à conta.","Escolha a conta, preencha o valor e, se quiser, uma observação.","Revise e confirme. Confira o novo progresso da meta e o saldo da conta."]},
    {"category":"goals","title":"Como concluir, continuar ou excluir uma meta?","tip":"Leia a confirmação para entender o destino do dinheiro antes de concluir ou excluir.","steps":["Abra Metas e localize a meta desejada.","Quando o objetivo for atingido, toque em Continuar ou concluir.","Para continuar, defina o novo objetivo e prazo; para concluir, confira as opções apresentadas e confirme.","Para excluir uma meta, use sua ação de exclusão e revise a confirmação."]},
    {"category":"groups","title":"Como criar um grupo para dividir despesas?","popular":true,"tip":"Compartilhe o código apenas com as pessoas que devem participar do grupo.","steps":["Abra Mais, Grupos e toque em Criar grupo.","Preencha o nome e, se quiser, a descrição. Confirme a criação.","Use Compartilhar para enviar o código aos participantes.","Quem recebeu o código deve abrir Grupos, tocar em Entrar por código e informar o código recebido."]},
    {"category":"groups","title":"Como registrar uma divisão e acertar os saldos do grupo?","tip":"O acerto só é concluído após a confirmação do recebedor.","steps":["Abra o grupo e a aba Divisões para cadastrar o lançamento.","Informe título, valor, tipo, participantes e modo de divisão. Anexe um comprovante quando exigido e confira o Preview.","Salve e consulte a aba Saldos para ver o resultado para cada participante.","Na aba Acertos, registre o valor e a forma de pagamento do acerto. O recebedor deve conferir e confirmar o recebimento."]},
    {"category":"groups","title":"Como consultar membros e encerrar um grupo?","tip":"Resolva os saldos pendentes antes de tentar encerrar o grupo.","steps":["Abra Mais, Grupos e selecione o grupo.","Consulte a aba Membros para conferir os participantes e as abas Divisões e Acertos para revisar o histórico.","Confira os saldos e os acertos que aguardam confirmação.","Se você tiver permissão para encerrar, use Encerrar grupo e siga a confirmação. O app informa se ainda houver pendências."]},
    {"category":"budgets","title":"Como criar, editar e acompanhar um orçamento?","tip":"O orçamento define um limite por categoria para o mês selecionado.","steps":["Abra a aba Orçamento e selecione o mês desejado.","Toque em Criar, informe o Limite Mensal e selecione a categoria.","Salve e compare Total Orçado, Total Gasto e o progresso das categorias.","Use as ações do orçamento para editar o limite ou excluir, conferindo a confirmação antes de remover."]},
    {"category":"accounts","title":"Como cadastrar e editar uma conta?","tip":"Confira o saldo inicial para que os próximos lançamentos partam do valor correto.","steps":["Abra Mais, Contas e inicie o cadastro de uma conta.","Preencha os dados solicitados e o saldo inicial.","Salve e confira a conta em Suas Contas e no resumo do patrimônio.","Use a edição da conta para atualizar seus dados; confira eventuais restrições antes de excluí-la."]},
    {"category":"accounts","title":"Como transferir valores entre contas?","tip":"Uma transferência move seu dinheiro entre contas; ela não é uma nova receita ou despesa.","steps":["Abra Mais, Contas e a ação de transferência.","Selecione contas diferentes para origem e destino.","Informe o valor e confira os dados solicitados antes de confirmar.","Confira os saldos e o registro em Transações. Nos detalhes, a ação Excluir transferência permite desfazer o movimento após confirmação."]},
    {"category":"voice","title":"Como registrar uma transação por voz?","tip":"Revise o resultado da interpretação antes de salvar. O recurso depende do seu plano.","steps":["Abra o lançamento de transação e escolha Por voz.","Permita o uso do microfone quando solicitado e grave a descrição do lançamento com valor e data.","Encerre a gravação e aguarde a análise do áudio.","Confira a transcrição, os avisos e os campos preenchidos. Corrija conta, categoria, valor e data se necessário e toque em Salvar."]},
    {"category":"voice","title":"Como ler uma nota ou comprovante com OCR?","tip":"Use uma imagem legível e confira os dados reconhecidos; a leitura pode precisar de correções.","steps":["Abra o lançamento de transação e escolha Leitura OCR.","Selecione Câmera, Galeria ou PDF e forneça o documento. Autorize o acesso solicitado pelo dispositivo quando necessário.","Aguarde a leitura e confira o texto reconhecido e os avisos da captura.","Revise descrição, valor, data, conta e categoria antes de salvar a transação."]},
    {"category":"reports","title":"Como consultar relatórios e limpar o filtro de período?","tip":"Tendências, evolução e formas de pagamento dependem do plano contratado.","steps":["Abra Mais, Relatórios para consultar receitas, despesas e saldo do período.","Toque no seletor de período e escolha um mês ou informe as datas de um Intervalo e aplique.","Consulte Despesas, Maiores Gastos e as análises disponíveis no seu plano.","Toque em Limpar filtro para voltar ao mês atual."]},
    {"category":"recurring","title":"Como criar e confirmar uma transação recorrente?","tip":"O Resumo Mensal Previsto é uma previsão; confira o extrato depois de confirmar o lançamento.","steps":["Abra Mais, Recorrentes e cadastre uma nova recorrência.","Preencha descrição, tipo, valor, dia, conta, categoria e método de pagamento. Ative Valor variável? quando o total mudar a cada mês.","Salve a regra e, no mês desejado, use Confirmar lançamento ou Confirmar valor do mês, informando o valor real quando solicitado.","Confira o lançamento no extrato e o indicador Confirmado este mês. Use Desfazer se precisar reverter a confirmação."]},
    {"category":"recurring","title":"Como editar, pausar ou excluir uma recorrência?","tip":"Confira os lançamentos já confirmados no extrato ao alterar uma regra.","steps":["Abra Mais, Recorrentes e localize a regra.","Use Editar para alterar os dados e salve.","Use Pausar para suspender a regra ou Retomar para reativá-la.","Para remover a regra, use Excluir recorrência e leia a confirmação antes de continuar."]},
    {"category":"imports","title":"Como importar transações de uma planilha?","tip":"Importação é um recurso Pro. Revise o arquivo para evitar lançamentos duplicados.","steps":["Prepare um arquivo CSV, XLS ou XLSX com as colunas description, amount, type, category, payment_method e date.","Use income para receitas, expense para despesas e datas no formato YYYY-MM-DD.","Abra Mais, Importar, toque em Clique para selecionar e escolha o arquivo.","Toque em Confirmar Importação e confira o resultado, eventuais erros e Últimos lotes. Verifique os lançamentos em Transações."]},
    {"category":"income-tax","title":"Como gerar o relatório de apoio ao Imposto de Renda?","tip":"O relatório é de apoio e não é importado diretamente no programa da Receita Federal. Recurso Pro.","steps":["Abra Mais, Imp. de Renda e selecione o ano.","Revise rendimentos, despesas, despesas dedutíveis e comprovantes anexados.","Toque em Exportar PDF ou Exportar planilha e aguarde a geração do arquivo.","Use as opções do dispositivo para salvar ou compartilhar. Confira os valores e recibos antes de usá-los na declaração."]},
    {"category":"plans","title":"Como consultar planos e gerenciar a assinatura?","tip":"Confira preço, período e condições apresentados pela loja antes de contratar.","steps":["Abra Mais, Planos para comparar os recursos e limites disponíveis.","Confira o plano atual e as opções de contratação ou teste exibidas para sua conta.","Para contratar, selecione a opção desejada e conclua o fluxo apresentado pela loja. Aguarde a atualização do acesso no app.","Para gerenciar ou cancelar uma assinatura feita no Google Play, abra a área de assinaturas da sua conta na loja."]},
    {"category":"profile","title":"Como editar meu perfil?","tip":"Confira o telefone com código do país e os dados do endereço antes de salvar.","steps":["Abra Mais e toque em Editar no cartão do perfil.","Atualize a foto e os campos disponíveis, como nome, telefone e data de nascimento.","Revise CEP, rua, número, UF, cidade e os demais dados que desejar informar.","Toque em Salvar Alterações e aguarde a confirmação."]},
    {"category":"profile","title":"Como ativar ou desativar o modo escuro?","tip":"A preferência de aparência é salva neste dispositivo.","steps":["Abra a aba Mais.","Localize Modo Escuro em Preferências.","Ative ou desative o controle para mudar a aparência do app.","Confira a nova aparência nas telas que utiliza."]},
    {"category":"security","title":"Como configurar a biometria e a autenticação em duas etapas?","tip":"Guarde o acesso ao seu autenticador para conseguir entrar novamente na conta.","steps":["Abra Mais, Privacidade e Segurança e consulte a seção Segurança.","Para usar Bloqueio por biometria, tenha uma biometria cadastrada no dispositivo e siga a validação apresentada.","Para ativar Autenticação em duas etapas, use seu aplicativo autenticador para ler o QR code apresentado.","Digite o código de seis dígitos e toque em Verificar. Confira também a opção Alertas de login e os Acessos recentes."]},
    {"category":"security","title":"Como ajustar a privacidade, exportar dados ou excluir minha conta?","tip":"Excluir a conta é irreversível. Exporte os dados que desejar manter antes de confirmar.","steps":["Abra Mais, Privacidade e Segurança.","Na seção Privacidade, ajuste Ocultar valores na tela inicial, Compartilhar estatísticas anônimas e Exigir comprovante em despesas de grupo.","Em Seus Dados, use Exportar meus dados para gerar uma cópia e acompanhe o resultado apresentado.","Se desejar encerrar a conta, toque em Excluir minha conta, leia a confirmação e preencha os campos solicitados. Confirme apenas se quiser concluir a exclusão."]},
    {"category":"notifications","title":"Como consultar notificações e configurar os alertas?","tip":"As notificações push também dependem da permissão do sistema do dispositivo.","steps":["Abra Mais, Notificações para consultar os avisos da sua conta.","Use Somente não lidas para filtrar e toque em um aviso para abrir seu destino quando disponível.","Use Marcar todas como lidas para atualizar a lista; Excluir todas remove os avisos da lista.","Abra Preferências para ajustar os tipos de alerta e a entrega de notificações disponíveis."]},
    {"category":"support","title":"Como encontrar um tutorial ou falar com o suporte?","tip":"Não envie senhas, códigos de autenticação ou dados completos do cartão ao suporte.","steps":["Abra Mais, Central de ajuda e digite uma palavra na busca ou selecione um assunto.","Toque na pergunta para abrir o passo a passo e a dica.","Se continuar com dúvida, use Chat para acessar o suporte interno, disponível no Plano Pro, ou E-mail para abrir seu aplicativo de e-mail.","Descreva o problema e os passos para reproduzi-lo, evitando incluir informações sensíveis."]},
    {"category":"support","title":"Como consultar informações do app, termos e política de privacidade?","tip":"As informações legais também podem ser consultadas pela tela Privacidade e Segurança.","steps":["Abra Mais e acesse Sobre.","Consulte as informações e a versão do aplicativo exibidas na tela.","Abra os links de Termos de Uso e Política de Privacidade para ler os documentos.","Volte à Central de ajuda se precisar de orientação sobre uma funcionalidade."]}
  ]$articles$::jsonb) loop
    article_order := article_order + 1;
    select id into category_id_value from public.help_categories where code = article->>'category';
    select id into article_id_value from public.help_articles
      where category_id = category_id_value and title = article->>'title'
      order by created_at, id limit 1;

    if article_id_value is null then
      insert into public.help_articles (category_id, title)
      values (category_id_value, article->>'title') returning id into article_id_value;
    end if;

    update public.help_articles set
      level = 'Iniciante', popular = coalesce((article->>'popular')::boolean, false),
      tip = article->>'tip', is_active = true,
      display_order = article_order
    where id = article_id_value;

    delete from public.help_article_steps where article_id = article_id_value;
    insert into public.help_article_steps (article_id, step_order, text)
      select article_id_value, ordinality::integer, value
      from jsonb_array_elements_text(article->'steps') with ordinality;
  end loop;
end;
